# Extract project name from Project_Information using regex
# Pattern: owner/repo
import re

def extract_project_name(text):
    if not text:
        return None
    # Find all owner/repo patterns
    matches = re.findall(r'([a-zA-Z0-9][\w.-]*/[\w.-]+)', text)
    if matches:
        return matches[0]
    return None

def extract_forks(text):
    if not text:
        return None
    # Match patterns like "5,782 forks" or "5782 forks" or "forks count of 988"
    # Try several patterns
    m = re.search(r'forks?\s+count\s+of\s+([\d,]+)', text, re.IGNORECASE)
    if m:
        return int(m.group(1).replace(',', ''))
    m = re.search(r'([\d,]+)\s+forks?', text, re.IGNORECASE)
    if m:
        return int(m.group(1).replace(',', ''))
    return None

